// Turns src/index.html into a JS module so the page function can serve it
// (with the latest published snapshot injected) without touching the filesystem.
import { readFileSync, writeFileSync } from "node:fs";
const html = readFileSync(new URL("./src/index.html", import.meta.url), "utf8");
writeFileSync(
  new URL("./netlify/functions/lib/template.mjs", import.meta.url),
  "// generated by build.mjs - do not edit\nexport default " + JSON.stringify(html) + ";\n"
);
console.log("template.mjs written (" + html.length + " bytes)");
